-- Profiles use existing registry identities and election-scoped ECI classifications.
-- The June 2024 Gazette includes all 543 constituencies, including unopposed Surat.
-- Additive evidence leaves current recognition, aliases and Page authority intact.
UPDATE public.political_organizations AS party
SET name = CASE WHEN party.name = party.short_name THEN evidence.name ELSE party.name END,
    profile_evidence = jsonb_build_array(evidence.fact) || party.profile_evidence,
    updated_at = now()
