  AND party.provenance_id IS NOT NULL
  AND NOT party.profile_evidence @> jsonb_build_array(evidence.fact);

UPDATE public.political_organizations AS party
SET profile_evidence = party.profile_evidence || jsonb_build_array(history.fact),
    updated_at = now()
FROM (VALUES
  ('ORG-PARTY-TDP', '{"kind":"founded","year":1982,"founder":"N. T. Rama Rao","sourceUrl":"https://www.telugudesam.org/life-and-history-of-our-founder/"}'::jsonb),
  ('ORG-PARTY-JSP', '{"kind":"registered","year":2014,"sourceUrl":"https://ceotelangana.nic.in/Reports%20and%20Accounts%20statements%20of%20State%20Level%20Political%20Parties/RUPS/2022-23/JANASENA_2022-23%2824A%20%26%20Audit%20Report%29.pdf"}'::jsonb),
  ('ORG-PARTY-BRS', '{"kind":"renamed","year":2022,"previousName":"Telangana Rashtra Samithi","sourceUrl":"https://www.eci.gov.in/eci-backend/public/pdf/report/2023/January/annual/Bharat%20Rashtra%20Samithi%20AA%202022-23.pdf"}'::jsonb)
) AS history(id, fact)
WHERE party.id = history.id
  AND party.org_type = 'political_party'
  AND party.provenance_id IS NOT NULL
  AND NOT party.profile_evidence @> jsonb_build_array(history.fact);

